import sys

def find_min_difference(n, points):
    min_diff = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            diff = abs(points[i][1] - points[j][1])
            if diff < min_diff and abs(points[i][0] - points[j][0]) > 1e-06:
                min_diff = diff
                min_x, max_x = float('inf'), float('-inf')

                for k in range(n):
                    if k != i and k != j:
                        if points[i][1] < points[k][1] < points[j][1]:
                            continue
                        dist = abs(points[k][1] - min(points[i][1], points[j][1])) + abs(points[k][0] - max(points[i][0], points[j][0]))
