            ni_map = {i: ni_map[i] for i in ni_map if ni_map[i] - nj(i, ni_map[i]) > 0}
            ni_map['0'] += len(ni_map) - len(ni_map.values())
            process_schedule = [0] * ((2 * sum(ni)) // max(ni))
            ni_iter = 0
            iterator = 0
            for loop in ni_map.keys():
                ni_iter += ni_map[loop]
                while ni_iter > 0:
