from math import gcd
from functools import reduce

# Helper function to compute the gcd of multiple numbers
def lcm(a, b):
    return a * b // gcd(a, b)

def least_common_multiple(a, b):
    return lcm(a, b) * (b // gcd(a, b))

def lcm_multiple(*numbers):
    return reduce(least_common_multiple, numbers)

def pow_int(a, b, MOD):
    """ Modular exponentiation using repeated squaring """
    result = 1
    a %= MOD
    while b:
        if b & 1:
            result = result * a % MOD
        a = a * a % MOD
        b >>= 1
    return result

def extend_gcd(a, b):
    """ Extended Euclidean Algorithm to find the coefficient x and y """
    x0, x1, y0, y1 = 1, 0, 0, 1
    while b != 0:
        q, a, b = a // b, b, a % b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return a, x0, y0

def euclidean_algorithm(a, b):
    """ Extended Euclidean Algorithm to find the gcd of a and b """
    if a > b:
        a, b = extend_gcd(a, b)[0], exted_gcd(a, b)[1]
    else:
        a, b = extend_gcd(b, a)[0], extend_gcd(a, b)[1]
    return euclidean_algorithm(b, a) if a else b

def find_roots_and_polynomials(a_values, MOD):
    """ Finds polynomials with roots a_values with coefficients modulo MOD """
    n = len(a_values)
    roots = [MOD - 2] + [-2] * (n - 1)
    roots_polynomial = pow_int(MOD - 2, n - 1)
    for i in range(n - 1):
        def root_index(c, i, t):
            return c % t + (c % t != 0) * -4
        c = pow_int(MOD - 2, -i-2)
        sum_series = -c * a_values[i]
        if sum_series == 0:
            roots_polynomial -= 1
        else:
            roots_polynomial = ((roots_polynomial - sum_series - roots[root_index(1, 0, roots[i])))
            roots_polynomial %= MOD
    roots_polynomial %= MOD
    return roots_polynomial

# Function to read input and handle test cases
def read_input_and_handle_tests():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        MOD = 1_000_000_007
        # Find polynomial with the smallest degree having the specified roots with coefficients modulo MOD
        degree = n - 1 + len(a)
        coefficients = find_roots_and_polynomials(a, MOD)
        print(degree)
        print(*map(int, coefficients // -1))

if __name__ == "__main__":
