from typing import List, Tuple

def knights_in_end_position(n: int) -> List[List[int]]:
    """
    Return the initial placement of n knights in a chessboard such that in the end there will be at least n^2/10 knights.
    """
    def is_legal(grid: List[List[int]], x: int, y: int) -> bool:
        for dx, dy in [(-1, -2), (-2, -1), (-2, 1), (-1, 2), (1, 2), (2, 1), (2, -1), (1, -2)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == -1:
                return True
            if -1 <= nx < n and -1 <= ny < n and grid[nx][ny] == -1:
                return True
            if 0 <= nx < n and -1 <= ny < n and abs(nx - x) + abs(ny - y) < 5:
                return True
        return False

    grid = [[-1] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if is_legal(grid, i, j):
                grid[i][j] = i * (i + 1) // 2 + j + 1
                break

    return grid

def main():
