def find_y(W, nnis, N):
    # Create a schedule that will always add W to y
    # We do this by iterating in order from min(nnis) to max(nnis)
    # And then cyclically repeating the order
    schedule = []
    max_nis = max(nc for nc in nnis)

    for ni in nnis:
        for _ in range((nc + 1) % max_nis + 1):
            schedule.append(nc + ni)

    # Sanity check to ensure we have exactly 2*N operations
    if len(schedule) != 2 * sum(nnis):
        return "No"

    # Check if the schedule allows for y == W
    if sum(schedule) == W:
        return "Yes\n" + " ".join(str(i) for i in schedule)
    else:
        return "No"

