from typing import List

class BridgeFinder:
    def __init__(self, graph: List[List[int]]):
        self.graph = defaultdict(list)
        for u, v in graph:
            self.graph[u].append(v)
            self.graph[v].append(u)

    def add_edge(self, u: int, v: int):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, v: int, parent: int, sptset: List[bool]):
        sptset[v] = True
        for neighbor in self.graph[v]:
            if neighbor != parent and not sptset[neighbor]:
                self.dfs(neighbor, v, sptset)

    def get_bridge(self, sptset: List[bool]):
        bridges: List[int] = []
        max_distance = -1
        for v in self.graph[::-1]:
            if not sptset[v]:
                for neighbor in self.graph[v]:
                    if neighbor != parent and not sptset[neighbor]:
                        dist = self.distance(v, neighbor)
                        if dist > max_distance:
                            max_distance = dist
                            bridges = [v, neighbor]
                        break
        return max_distance - self.distance(bridges[0], bridges[1])

    def distance(self, u: int, v: int):
        if u == v:
            return 0
        x = self.graph[u]
        y = self.graph[v]
        return min(x.index(u) + y.index(v), y.index(u) + x.index(v))

