# Function to calculate shortest path with Edmonds-Karp
def get_shortest_path(graph: List[List[int]], root: int) -> List[int]:
    n = len(graph)
    # Calculate the parent list: stores vertices of the Shortest path tree
    parent = [0] * n
    send = [0] * n
    spt_set = [False] * n

    def bfs():
        # Six-time setup of the queue
        queue = [root]
        distance_from_u = {}
        spt_set[root] = True
        distance_from_u[root] = 0
        while queue:
            u = queue.pop()
            for neighbor in graph[u]:
                if not spt_set[neighbor]:
                    spt_set[neighbor] = True
                    distance_from_u[neighbor] = distance_from_u[u] + 1
                    parent[neighbor] = u
                    send[neighbor] = send[u] + 1  # used edges in graph
                    queue.append(neighbor)

    bfs()
    return distance_from_u, parent

