def euler_sequence(nums):
    primes_map = defaultdict(lambda: -1)
    for num in nums:
        curr_factors = {i: False for i in range(2, (sqrt(num // 2)) + 1)}
        for factor in range(2, int(sqrt(num // 2)) + 1):
            if num % factor == 0:
                curr_factors.setdefault(factor, True)
                while num % factor == 0:
                    num //= factor
                    if curr_factors.get(factor):
                        curr_factors[factor] = False

        curr_sequence = []
        for factor, flag in curr_factors.items():
            if flag:
                curr_sequence.append(euler_totient(factor))

        last = num % 2 + 1
        keys = sorted(primes_map.keys())
        added_primes = 0
        for factor in keys:
            if factor <= last:
                if primes_map[factor] == -1 or (last - primes_map[factor]) > factor:
                    primes_map[factor] = -added_primes
                    last -= added_primes
                    added_primes += euler_totient(fact)

    output = []
    for num in nums:
