def ways_to_visit(max_planets, times_visited, max_moves):
    if max_planets == 1:
        return times_visited

    min_moves = math.ceil(max_planets * math.sqrt(times_visited))
    if max_moves < min_moves:
        return 0

    # Add max_planets-1 available moves
    result = (times_visited * (times_visited - 1)) // 2
    denominators = defaultdict(int)
    for i in range(min_moves):
        denominators[i, 0] = pow(i, i + 1 / 2, 1000000007)
    for i in range(max_moves - min_moves):
        denominators[i, min_moves + i] = modpow(min_moves + i, min_moves + i + 2, 1000000007) * pow(min_moves - i, 2, 1000000007) % 1000000007

    for i in range(max_planets - min_moves):
        denominators[0, i], denominators[i, 0] = denominators[i, 0], denominators[0, i]
    den = _factorial(max_planets) % 1000000007
    for k, v in denominators.items():
