def catalan(n, mod):
    series = 1
    for k in range(1, n+1):
        series = series * k % mod
        series = pow(series, 2, mod)
    return series

def findRoads(people, v, mod, wheel):
    ans = 1
    for i in range(1, v):
        if wheel[i] != -1:
            for j in range(i):
                if wheel[i-j-1] == j + 1:
                    ans = ans * (catalan(i + 1 - j, mod)) % mod
    return ans % mod

def solve():
    n, k, m = map(int, input().split())
    dp = [0] * (n + n)
    dp[m] = catalan(k + 2, 10**9 + 7)
    wheel = [-1] * n
    cycle = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (j - i) % m == 0:
                cycle += 1
                dp[j] = (dp[j] - dp[i - 1] + 10**9 + 7) % 10**9 + 7

    res = 0
    while n:
        res += findRoads(n, k, 10**9 + 7, dp)
        crystal = n // m + (n & 1)
        res %= 10**9 + 7
        wheel[n % m - 1] = crystal
        n = crystal
    return res

