def min_projection_difference(*, n, segments):
    min_diff, max_x = float('inf'), 0
    for _, _, y in segments:
        max_x = max(max_x, y)

    # Sort segments by x1 and, if the same, by y
    segments.sort(key=lambda x: (x[0], -x[1]))

    for _, _, y in segments:
        # Calculate projections along possible vectors (1, -1), (1, -0.5), ..., (-1, -1)
        for vector in (1, -1), *[(1/2**i) for i in range(12)]:
            new_diff = vector * (max_x - y)

            # Check if this difference is possible
            if abs(new_diff) > min_diff:
                break
            else:
                min_diff = abs(new_diff)

            # Ensure they don't intersect
            for _, y1, _ in segments:
                if vector * max_x - new_diff <= y1 and vector * max_x - y >= y1:
                    break

            else:
                # No intersection found, check if this is global minimum
                min_diff = new_diff

    return min_diff

