from math import sqrt
from typing import List

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def polynomial_degree(t: int, n: int, as_primes: List[int]) -> int:
    prime_factors = sorted(as_primes)
    start_prime = prime_factors[0]
    prime_list = [[start_prime, 0], [0 for _ in range(n - 1)]]

    for i, factor in enumerate(prime_factors[1:], 1):
        if factor == start_prime:
            prime_list[1][i] += 1
        else:
            prime_list.append([factor, 0])
            last_prime = prime_factors[i]
            factor -= last_prime
            power = int(sqrt(factor) + (factor % 2 != 0))
            j = 0
            while prime_factors[i] <= power:
                prime_list[i][j] += 1
                j += 1
            i += 1

    result_prime = prime_list.copy()
    heapq.heapify(result_prime)
    prime_power = []
    while result_prime:
        factor, power = heapq.heappop(result_prime)
        factor1 = factor
        while result_prime and factor == result_prime[0][0]:
            factor1 += result_prime[0][0]
            heapq.heappop(result_prime)
        prime_power.append(str(factor1) + ' ' + str(power))

    polynomial_string = ' '.join(prime_power)
    return int(polynomial_string.strip())

def main():
    n = int(input())
    while n > 0:
        n -= 1
        t = int(input())
        prime = set()
        for _ in range(t):
            as_ints = list(map(int, input().split()))
            primes = list(set([int(edge[1]) for edge in as_ints if edge[0] == '0']))
            prime = prime.union(primes)
        prime = sorted(list(prime))
        print(polynomial_degree(t, len(prime), prime))

if __name__ == "__main__":
    main()
